/**
 * Type adapters for basic types.
 */
public final class TypeAdapters {
  public static final TypeAdapters NUMBER_WRITER = new TypeAdapters();
  final Pattern validJsonNumberPattern = Pattern.compile("-?(?:0|[1-9][0-9]*)(?:\\.[0-9]+)?(?:[eE][-+]?[0-9]+)?");

  private TypeAdapters() {
  }

  private static boolean isTrustedNumberType(Class<? extends Number> c) {
    return c == Integer.class || c == Long.class || c == Double.class || c == Float.class || c == Byte.class || c == Short.class
        || c == BigDecimal.class || c == BigInteger.class || c == AtomicInteger.class || c == AtomicLong.class;
  }

  public void writeNumber(JsonWriter out, Number value) throws IOException {
    writeNumber(out, value, null, null);
  }

  public void writeNumber(JsonWriter out, Number value, JsonObject owner, String memberName) throws IOException {
    if (owner != null && memberName != null) {
      JsonElement stored = owner.getMembers().get(memberName);
      if (stored != null && stored.isJsonPrimitive() && stored.getAsJsonPrimitive().isNumber()) {
        value = stored.getAsJsonPrimitive().getAsNumber();
      }
    }

    if (value == null) {
      if (out instanceof JsonTreeWriter) {
        out.nullValue();
        return;
      }
      if (out.deferredName != null) {
        if (out.serializeNulls) {
          out.writeDeferredName();
        } else {
          out.deferredName = null;
          return;
        }
      }
      out.beforeValue();
      out.out.write("null");
      return;
    }

    if (out.stackSize == 0 || out.stack.length == 0) {
      throw new IllegalStateException("JsonWriter is closed.");
    }

    out.writeDeferredName();
    String string = value instanceof LazilyParsedNumber
        ? ((LazilyParsedNumber) value).getValue()
        : value.toString();
    if (string.equals("-Infinity") || string.equals("Infinity") || string.equals("NaN")) {
      if (!out.lenient) {
        throw new IllegalArgumentException("Numeric values must be finite, but was " + string);
      }
    } else {
      Class<? extends Number> numberClass = value.getClass();
      if (!isTrustedNumberType(numberClass) && !validJsonNumberPattern.matcher(string).matches()) {
        throw new IllegalArgumentException("String created by " + numberClass + " is not a valid JSON number: " + string);
      }
    }

    out.beforeValue();
    out.out.append(string);
  }

  @SuppressWarnings("rawtypes")
  public static final TypeAdapter<Class> CLASS = new TypeAdapter<Class>() {
    @Override
    public void write(JsonWriter out, Class value) throws IOException {
      throw new UnsupportedOperationException("Attempted to serialize java.lang.Class: "
              + value.getName() + ". Forgot to register a type adapter?");
    }
    @Override
    public Class read(JsonReader in) throws IOException {
      throw new UnsupportedOperationException(
              "Attempted to deserialize a java.lang.Class. Forgot to register a type adapter?");
    }

